      "card_ids": ["C17"],
      "claim": "Estazolam, a benzodiazepine with chlorophenyl and heteroaromatic features, has 87% oral bioavailability in healthy volunteers, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Alprazolam, a triazolobenzodiazepine with chlorophenyl and heteroaromatic features, has absolute oral bioavailability generally exceeding 90% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Clobazam, a benzodiazepine with chlorophenyl and heteroaromatic features, has oral bioavailability reported as 100% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Adinazolam, a closely related triazolobenzodiazepine, has absolute oral bioavailability of 39% in healthy volunteers, still well above the 20% threshold and supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Triazolam, a structurally similar triazolobenzodiazepine, has oral bioavailability of 55% ± 20% in healthy subjects, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Loxapine, a tricyclic CNS agent with chlorophenyl features, has systemic availability of 0.29, above the 20% threshold and supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All relevant experimental analogues with measurable oral bioavailability show F values above 20%, mostly in the 40–100% range, despite low Morgan similarity. The query's lipophilic, heteroaromatic CNS-like structure is consistent with good absorption and high oral bioavailability.",
  "evidence_gaps": [
    "No direct pharmacokinetic data exist for the exact query scaffold.",
    "All evidence molecules have low Morgan similarity (<0.28), limiting structural transferability.",
    "Conflicting bupropion bioavailability reports (10% vs >80%) reduce the reliability of that analogue and were not used as primary evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

